{
  "contract": "SimpleSalesEth",
  "closure": {
    "site_function": "buy",
    "site_call": ".transferFrom",
    "functions": [
      "withdrawAllFailedCredits"
    ],
    "justification": "withdrawAllFailedCredits affects exposed storage variables _ethBal and failedTransferCredits."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "withdrawAllFailedCredits"
    ],
    "nesting_bound": {
      "withdrawAllFailedCredits": 1
    }
  },
  "phases": {
    "function": "buy",
    "pre": {
      "name": "pre",
      "from_marker": "start_pre",
      "to_marker": "end_pre"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "start_exposed",
      "to_marker": "end_exposed"
    },
    "post": {
      "name": "post",
      "from_marker": "start_post",
      "to_marker": "end_post"
    },
    "linearization_point": "end_exposed"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_failedTransferCredits == snapPre + inFlight",
    "stable_formula": "_sum_failedTransferCredits == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_failedTransferCredits <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of failedTransferCredits is conserved across the callback window, allowing the target property to hold."
  }
}
